WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (416::BIGINT, 'Lo mismo que el comentario de abajo. Uno cree que es amistoso hasta que se da cuenta que en realidad es hostigador y se empieza a aprovechar de su cercanía con las estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-09-10T00:00:00+00:00'::TIMESTAMPTZ, '51f91292419c8b5913bd85bccff36d73e60dbd05e9dfb5a05e7dc1b415b8cecb'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'Se hace el super amable, pero es demasiado acosador, se me queda viendo las tttas, yo pensé que le caía super bien, pero para saludarme siempre era de beso en el cachete y abrazo. Hasta que un día me toco la cintura y hablaba todo tembloroso. Es un ascooo y sino me creen vivanlo ustedes (mujeres)'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-10T00:00:00+00:00'::TIMESTAMPTZ, '40bb423130546f90becb68b4c8b526afeffbdf31edf7692e70ddcf4802b80746'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'no , no y nop... malo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'La participación importa']::TEXT[], '2025-05-22T00:00:00+00:00'::TIMESTAMPTZ, '83bc643df035c84b23d7b73c0d7d63071bf7bd100063dfc4541e95c5457c8186'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'El curso es muy interesante, el profesor es amable y ayuda mucho si uno pregunta. A veces es ambiguo con los instructivos y cuesta entender que quiere realmente. Es importante ir a consulta. El curso fue semi-virtual y solo hubo que asistir prescencial las primeras semanas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd870654136640f794c031997ebb572804ff9b0ac46f5b09424343766e1ac6efe'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'Es muy buen profesor, es el curso en el que más he aprendido porque se utilizan bastantes herramientas y enseña un poco de especificación y diseño de proyectos (curso que hace falta en EL), trae varias empresas a dar charlas que le pueden dar oportunidad de trabajo. Si van a consulta les va bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2023-08-21T00:00:00+00:00'::TIMESTAMPTZ, 'b17c8feab04d0a13a3ea6d03554e475d35787e3760bc91c8816385d3c47edf1a'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '67929eb2b341196862fcba68d3673455fcb6c2f7b739c23bc029a1acdbac4380'::TEXT, ARRAY[3557]::BIGINT[]),
    (416::BIGINT, 'Es 1 solo proyecto en todo el semestre con varios entregables, pero todas las semanas hay que hacer un avance y una presentacion, quita demasiado tiempo en la semana. No lo recomiendo si esta llevando muchos cursos, pero se pasa de fijo con buena nota'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-12-27T00:00:00+00:00'::TIMESTAMPTZ, '723ccfb78cca7848b1f12f3b801e9bb68f4197dacd97a338329d6f1689429b61'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-11-13T00:00:00+00:00'::TIMESTAMPTZ, 'a1f7eb70d89687628b486c83b566860765a47dce7be1d4c277d6bd59bda1b7ac'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'El profe es exigente, pero se aprende mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '0befce5d6df3e00152097121c9ba3b6e35155c938556b94eae89fd3d488f7ba3'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'Un único proyecto con evaluaciones en 2 avances y 1 trabajo final + una bitácora individual y evaluaciones entre los miembros del grupo. Exposiciones (sin calificación) casi 2 veces a la semana. Grupos escogidos por Johan. Usualmente pide las cosas "para ayer". Johan lo hace de 4 créditos, pasable.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '546c4bd0e0c34d7529e7a5d2b7d87ed46303b7f1ea1e37031f04a84af0809405'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'Los exámenes /quices son fáciles, el proyecto es a lo que hay que dedicarle todo el tiempo posible. Es bastante largo, hay que entender muy bien lo que se está haciendo, el profe es bueno porque obliga a explicar y diseñar cada parte del proyecto y que todo quede bien definido. Ayuda mucho consulta'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '44b26ac755977cced824e157d4cec2be99c6824d7eeddbb5ce88581ab1f4bbe1'::TEXT, ARRAY[1313]::BIGINT[]),
    (416::BIGINT, 'El curso en sí es super fácil (tareas y exámenes), pero el proyecto... Ish... Ya no va a dar Arqui'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '78e33ed82b464afed4590338179da2725a9542eefa4f3d6a6747432589ccfffb'::TEXT, ARRAY[2973]::BIGINT[]),
    (416::BIGINT, 'Asume que todo lo sabemos, califica duro y no explica nada.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'cf64886f8609a055e4fc4f239a5733848235e2aa26f90e453b112c6e0b5ac7fd'::TEXT, ARRAY[1313]::BIGINT[]),
    (416::BIGINT, 'El curso es confuso, hay bastante materia y poca practica, el proyecto es relativamente largo(asegúrese de tener un buen grupo que trabaje) pero el profe es buena gente, si ocupa más tiempo para entregar algo él lo da. Elijan bien el tema del proyecto.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'cc162443407f8aa2d325b57943eb0a3aad5e4cf62a757ce23524b76298949658'::TEXT, ARRAY[1032]::BIGINT[]),
    (416::BIGINT, 'Las clases son aburridas y asume que ya se sabe del tema, el proyecto es largo y muy pesado pero se saca, los exámenes son relativamente fáciles virtuales'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, '3cbf7ab69e756660233179d36b417fd1284d9af2d77bb03148bd6f186766ca6b'::TEXT, ARRAY[2973]::BIGINT[]),
    (416::BIGINT, 'dicen que era bueno pero nadie le dijo que ya esta roco'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '1b08a40116a8b38ea1b5efd6f84e7173c580bd60902def8b65c5341984ebdfce'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'Muy buen profe, ayudo bastante a comprender bien todo el procedimiento y lo saca a uno de la conformodidad.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, '4c7ba17ae52da1b06ffd25dc3fe97b50b13d791d5aa2fcf8dc131456f6b0f616'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'No sé que le pasó. Antes era mejor profe. Para este curso piensa que uno sabe de todo y casi ni se ven cosas de electrónica ). Un día dice una cosa y al siguiente te dice que todo está malo. Las pocas clases que da son un pérdida de tiempo. De los peores cursos que he llevado.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'ced11407fdebaf10e6cf86ed286fbae678c8aae9bb05d950adaf0fb002ff85e2'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'dicen que era bueno, pero ya no. por andar con una compa solo deja trabajos...'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'de5a74b27193409001097f4c5308f361f0be856e68acbf471b1e8e48839060a4'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'Paso de ser excelente profesor, a ser parte del resto. Pésima retroalimentación, hoy te pide una cosa y la otra semana te evalúa otra. No da rúbricas ( por que en Holanda no daban JAJAJA), él se las inventa, califica subjetivo, y no sabe que es objetividad. Sin derecho a reclamarle su evaluación...'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2020-06-10T00:00:00+00:00'::TIMESTAMPTZ, '8d696b5fd9dfb0aa3b9f3cc8a04e0f81450158449b18584badd2abbde33c3870'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'Pésimo profesor. Se dedica solo a pedir trabajos y a poner a exponer a los alumnos los temas que él debería dar. Cree que está en una empresa donde él es el jefe, y su complejo de superioridad hace que no escuche otros puntos de vista. Eviten el curso!'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'd971b2987fbded5fec475621e0e919ebefe047ca357e571a10211f8bab880dc2'::TEXT, ARRAY[1354]::BIGINT[]),
    (416::BIGINT, 'Buena gente. Si se busca en consulta, ayuda con el curso pero es un curso que depende más del trabajo en equipo. Se utilizan muchos cursos pasados.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4bfacd60161697db55f0e467b8539f0ba24e262c12e3bab5c0fa5c32ea51d608'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'El curso es sencillo, pero demanda mucho tiempo y trabajar en equipo se vuelve crítico a este punto por que los grupos son grandes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2019-12-15T00:00:00+00:00'::TIMESTAMPTZ, '754c07235d82b6a3aecd6d4a593b6330c06dc8f077bae711058c6f4cf1d03551'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'Es muy buena nota y las clases las hace cortas. Aunque no es obligatorio ir es importante pues muchas cosas que se ven en clase salen en el examen. Entre las cosas malas estan que deja proyectos algo volados y no hace ejercicios de practica. Deja trabajos de puntos extra que ayudan bastante al final'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'bb40273b2b459947b819e8acde47994c2cf857cb7036a4cbf11a39c9c9db372c'::TEXT, ARRAY[1313]::BIGINT[]),
    (416::BIGINT, 'Muy buen Profe, de los mejores que he tenido. Se preocupa mucho por que uno aprenda'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2019-11-05T00:00:00+00:00'::TIMESTAMPTZ, '3d2a8bef8bec9160de1a4c13280e4be292973e3a7b60be4d0af5341a5cfe978b'::TEXT, ARRAY[1032]::BIGINT[]),
    (416::BIGINT, 'Muy buen profesor para este curso, maneja muy bien los contenidos del curso y además se preocupa por que el grupo funcione como un equipo de trabajo. Es un curso donde hay muchos trabajos y desde el inicio se debe trabajar bastante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2019-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'c779607c5b66274af73c95adf10cb351189419eb6ed6cb99d6a7928dfaf94c85'::TEXT, ARRAY[1330]::BIGINT[]),
    (416::BIGINT, 'Literal el peor profesor que he tenido, no explicó ni un tercio de la materia y solo llevaba unas "practicas generales" una clase antes del examen. Es fácil pasarle, pero si quieren aprender de verdad busquen otro profe...'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'bb3f31a025cada1fd9c0208ccc70b32517a82c9e74581e3055056080358befbe'::TEXT, ARRAY[1286]::BIGINT[]),
    (416::BIGINT, 'No sirve'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-27T00:00:00+00:00'::TIMESTAMPTZ, 'ee649410b6959c24c6104eca550e8ccbdbbaa7d4d3b6bdc5324fe775c2126df6'::TEXT, ARRAY[1301]::BIGINT[]),
    (416::BIGINT, 'Excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-02-07T00:00:00+00:00'::TIMESTAMPTZ, '73e9fdcfa4e22b0d7d0bb1319faceb903fcc96f7a4fb9b7fbc72e0d2ed496387'::TEXT, ARRAY[1301]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
